# ---------------------------------------------------------------------------
# AUTO-GENERATED by Claude Code
# Purpose: `ds ui fonts`: update the JetBrainsMono Nerd Font that delulu-smash ships in
#          services/ui/assets/nerd_fonts/ (regular + bold woff2, OFL.txt, VERSION) from a
#          Nerd Fonts GitHub release. Why it is bundled: spec/services/ui/dependencies.md.
# ds::external-source: checked 2026-11-19 https://github.com/ryanoasis/nerd-fonts/releases
#   taken from it: the release's asset JetBrainsMono.tar.xz and the file names inside it
#   (JetBrainsMonoNerdFont-{Regular,Bold}.ttf, OFL.txt), the "latest" tag via GitHub's API
# ---------------------------------------------------------------------------
from __future__ import annotations

import json
import shutil
import tarfile
from pathlib import Path
from tempfile import TemporaryDirectory

import typer
from ds.util import http
from ds.util.const import REPO_DIR

__all__ = ["FONTS_DIR", "bundled_version", "update_fonts"]

FONTS_DIR = REPO_DIR / "services" / "ui" / "assets" / "nerd_fonts"
REPO = "ryanoasis/nerd-fonts"
ARCHIVE = "JetBrainsMono.tar.xz"
# the release's TTF -> the woff2 the page loads (app.css @font-face)
FILES = {
    "JetBrainsMonoNerdFont-Regular.ttf": "JetBrainsMonoNerdFont-Regular.woff2",
    "JetBrainsMonoNerdFont-Bold.ttf": "JetBrainsMonoNerdFont-Bold.woff2",
}
LICENSE = "OFL.txt"
DOWNLOAD_TIMEOUT_S = 300


def bundled_version() -> str | None:
    """The Nerd Fonts release the bundled files come from, eg 'v3.4.0'."""
    path = FONTS_DIR / "VERSION"
    return path.read_text(encoding="utf-8").strip() if path.exists() else None


def _get(url: str, name: str, **kwargs: object) -> bytes:
    try:
        with http.request("GET", url, source="nerd-fonts", name=name, follow_redirects=True, **kwargs) as (resp, _):
            resp.raise_for_status()
            return resp.content
    except Exception as error:  # httpx2's network and status errors alike
        typer.echo(f"GitHub request failed ({error}). The bundled fonts are unchanged.", err=True)
        raise typer.Exit(1) from error


def latest_release() -> str:
    """The newest release's tag, eg 'v3.5.1'."""
    body = _get(f"https://api.github.com/repos/{REPO}/releases/latest", "latest release")
    return json.loads(body)["tag_name"]


def _unpack(archive: Path, into: Path) -> None:
    """Take only the files we use out of the release archive; refuse if one is missing."""
    wanted = {*FILES, LICENSE}
    with tarfile.open(archive) as tar:
        members = [member for member in tar.getmembers() if Path(member.name).name in wanted]
        missing = wanted - {Path(member.name).name for member in members}
        if missing:
            typer.echo(f"{ARCHIVE} has no {', '.join(sorted(missing))}: the bundled fonts are unchanged.", err=True)
            raise typer.Exit(1)
        for member in members:
            member.name = Path(member.name).name  # flat, whatever folder the archive uses
            tar.extract(member, into, filter="data")


def to_woff2(ttf: Path, out: Path) -> None:
    """The whole font as woff2 (no subsetting: every icon stays available)."""
    from fontTools.ttLib import TTFont  # here: a dev dependency, needed by this command only

    font = TTFont(ttf)
    font.flavor = "woff2"
    font.save(out)


def update_fonts(version: str | None) -> None:
    """Replace the bundled fonts with release `version` (default: latest), all or nothing."""
    current = bundled_version()
    tag = version or latest_release()
    typer.echo(f"Bundled: Nerd Fonts {current or '(unknown)'} ({FONTS_DIR.relative_to(REPO_DIR)}/VERSION)")
    if tag == current:
        typer.echo(f"Bundled fonts are already Nerd Fonts {tag}: nothing to do.")
        return
    url = f"https://github.com/{REPO}/releases/download/{tag}/{ARCHIVE}"
    typer.echo(f"Downloading {ARCHIVE} ({tag})...")
    with TemporaryDirectory() as tmp:
        work = Path(tmp)
        (work / ARCHIVE).write_bytes(_get(url, f"{ARCHIVE} {tag}", timeout=DOWNLOAD_TIMEOUT_S))
        _unpack(work / ARCHIVE, work)
        for ttf, woff2 in FILES.items():
            to_woff2(work / ttf, work / woff2)
        # every new file exists: only now replace the bundled ones
        FONTS_DIR.mkdir(parents=True, exist_ok=True)
        for name in [*FILES.values(), LICENSE]:
            shutil.move(work / name, FONTS_DIR / name)
    (FONTS_DIR / "VERSION").write_text(f"{tag}\n", encoding="utf-8")
    sizes = ", ".join(f"{name} ({(FONTS_DIR / name).stat().st_size / 1e6:.2f} MB)" for name in FILES.values())
    typer.echo(f"Wrote {sizes}, {LICENSE}")
    typer.echo(f"VERSION: {current or '(unknown)'} -> {tag}. Reload the page to see it; commit the folder to share it.")
